import java.io.*;

public class Main {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) != 0) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int k = fs.nextInt();

        int[] fact = new int[n + 1];
        int[] invFact = new int[n + 1];
        int[] s = new int[n + 1];

        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % MOD);
        }

        invFact[n] = (int) modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = (int) ((long) invFact[i] * i % MOD);
        }

        s[1] = 1;
        long terminal = 0;

        for (int i = 2; i <= n; i++) {
            long removed = 0;
            int t = i - k;

            if (t >= 1) {
                long start = (t == 1) ? 1 : s[t - 1];
                long product = (long) fact[i - 2] * invFact[t - 1] % MOD;
                removed = start * product % MOD;
            }

            long current = ((long) i * s[i - 1]
                    - (long) (i - 1) * removed) % MOD;
            if (current < 0) {
                current += MOD;
            }
            s[i] = (int) current;

            terminal = (long) (i - 1) * ((terminal + removed) % MOD) % MOD;
        }

        long successful = (s[n] + terminal) % MOD;
        long answer = (fact[n] - successful + MOD) % MOD;
        System.out.println(answer);
    }

    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }
}
